          "개비스콘더블액션현탁액은 (유)옥시레킷벤키저가 2008년 2월 11일 허가받은 알긴산 기반 위식도역류 치료제예요. 식약처 품목번호 200801645, 일반의약품, ATC 분류 A02BX(위식도역류 질환 치료제 기타)예요. 일반 제산제(A02A 계열)와 다른 카테고리에 속하는 약이에요. 성상은 \"페퍼민트향이 나는 미황색~크림색의 현탁액\"이라고 식약처 허가사항이 명시했어요.\n\n식약처 등록 원료약품 분량은 100mL 중 알긴산나트륨 5g(건조물 4.375g), 탄산칼슘 3.25g, 탄산수소나트륨 2.13g 3성분이에요. 1포 10mL당 환산하면 알긴산나트륨 500mg, 탄산칼슘 325mg, 탄산수소나트륨 213mg이에요. 작용 메커니즘이 일반 제산제와 다른 게 핵심이에요.\n\n알긴산나트륨은 갈조류(미역·다시마)에서 추출한 천연 다당류로, 위의 산성 환경에서 알긴산 젤로 변해요. 탄산수소나트륨이 위산과 반응해 이산화탄소를 발생시키면 알긴산 젤이 가벼워져 위 내용물 위에 떠올라 \"raft(뗏목)\" 층을 만들어요. 이 raft가 식도로 위 내용물·위산이 역류하는 걸 물리적으로 차단해요. 동시에 탄산칼슘·탄산수소나트륨이 위산을 중화해요. 이게 \"더블액션(이중 작용)\"이라는 이름의 의미예요.",
