          "식약처 허가사항이 명시한 효능효과는 \"산 역류, 속쓰림, 위 내용물의 역류로 인한 소화불량(예를 들어 식사 후, 임신 중, 역류성 식도염과 동반하는 경우)\"이에요. 12포 박스라고 적응증이 다른 게 아니라 같은 200801645 품목번호의 1포 단위 그대로예요.\n\n작용은 두 갈래(이중 작용)예요. 첫째, 알긴산 raft가 위 내용물·위산이 식도로 역류하는 걸 물리적으로 막아요. 식도 점막에 위산이 직접 닿지 않으니 역류성 식도염의 \"가슴 타는 통증\"이 빠르게 줄어요. 둘째, 탄산칼슘·탄산수소나트륨이 위산을 중화해 일반 제산 효과를 더해요.\n\n적응증에 \"임신 중\" 역류가 명시된 게 특징이에요. 임신 후반기에 자궁이 위를 압박해 생기는 역류성 식도염은 흔하고, 알긴산은 위장에서 흡수되지 않아 임부에게 비교적 안전한 옵션으로 알려져 있어요. 12포 박스는 임신 중반~후반에 1주일 정도 가볍게 시도해보고 효과가 있다면 산부인과 상담을 받아 지속 여부를 결정하는 패턴에 어울려요.",
